 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 8 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)
            if maxr - minr < 2 or maxc - minc < 2:
                continue
            border = set(cells)
            # A hollow rectangle has a complete monochrome perimeter.
            if (all((minr, x) in border and (maxr, x) in border for x in range(minc, maxc + 1)) and
                all((y, minc) in border and (y, maxc) in border for y in range(minr, maxr + 1))):
                for y in range(minr + 1, maxr):
                    for x in range(minc + 1, maxc):
                        if grid[y][x] == 8:
                            out[y][x] = 7
    return out
